import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;import 'package:flutter/foundation.dart' show defaultTargetPlatform,kIsWeb,TargetPlatform;
class DefaultFirebaseOptions{static FirebaseOptions get currentPlatform{if(kIsWeb)throw UnsupportedError('Run flutterfire configure to generate web Firebase options.');switch(defaultTargetPlatform){case TargetPlatform.android:case TargetPlatform.iOS:case TargetPlatform.macOS:case TargetPlatform.windows:case TargetPlatform.linux:throw UnsupportedError('Run flutterfire configure for this target.');default:throw UnsupportedError('Unsupported platform');}}}
